function stopPageEntry(){
 try{entryObserver?.disconnect()}catch{}
 entryObserver=null;
 for(const block of entryBlocks){block.classList?.remove('entry-ready','entry-visible');block.style?.removeProperty('--entry-delay')}
 entryBlocks=[];
}
function animatePageEntry(container){
 stopPageEntry();
 if(typeof IntersectionObserver!=='function'||typeof window==='undefined'||typeof window.matchMedia!=='function')return;
 try{
  if(!window.matchMedia('(prefers-reduced-motion: no-preference)').matches)return;
  const blocks=Array.from(container?.children||[]).filter(block=>block.matches?.('section, details, .overview-status, .review-summary, .segmented'));
  if(!blocks.length)return;
  const observer=new IntersectionObserver(entries=>{
   if(entryObserver!==observer)return;
   for(const entry of entries){if(entry.isIntersecting){entry.target.classList.add('entry-visible');observer.unobserve(entry.target)}}
  },{threshold:0,rootMargin:'0px 0px -8px 0px'});
  entryObserver=observer;entryBlocks=blocks;
  blocks.forEach((block,index)=>{block.style.setProperty('--entry-delay',`${Math.min(index,3)*40}ms`);block.classList.add('entry-ready');observer.observe(block)});
 }catch{stopPageEntry()}
}
function replacePageContent(html,animate=false){
 stopPageEntry();
 const content=$('#page-content');if(!content)return;
 content.innerHTML=html;
 if(animate)animatePageEntry(content);
}

async function api(path,options={}) {
 const {envelope=false,...requestOptions}=options;
 const opts={credentials:'same-origin',...requestOptions,headers:{Accept:'application/json',...(options.headers || {})}};
 if(opts.body!==undefined){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(opts.body)}
 if(opts.method && !['GET','HEAD'].includes(opts.method) && state.me?.csrfToken)opts.headers['X-CSRF-Token']=state.me.csrfToken;
 let response;
 try {response=await fetch(`/api/v1${path}`,opts)} catch {throw new Error('暂时无法连接网站，请检查网络后重试。')}
 let payload;try{payload=await response.json()}catch{throw new Error('服务暂时不可用，请稍后重试。')}
 if(!response.ok){if(response.status===401 && path!=='/auth/login'){state.me=null;closeModal();renderLogin()};const err=new Error(payload.error?.message || (response.status===409?'记录已更新，请刷新后重新编辑。':'操作失败，请稍后重试。'));err.status=response.status;err.code=payload.error?.code;throw err}
 return envelope?payload:payload.data;
}
function toast(message,error=false){const node=document.createElement('div');node.className=`toast${error?' error':''}`;node.setAttribute('role',error?'alert':'status');node.textContent=message;$('#toasts').append(node);while($('#toasts').children.length>3)$('#toasts').firstElementChild.remove();setTimeout(()=>node.remove(),error?8000:4500)}
function empty(title,description='',action=''){return `<div class="empty"><span class="empty-icon">${icon('articles',22)}</span><h3>${e(title)}</h3>${description?`<p>${e(description)}</p>`:''}${action}</div>`}
function badgeMode(mode){return `<span class="badge ${mode==='automatic'?'up':mode==='mixed'?'neutral':''}">${e(modeLabels[mode]||modeLabels.unknown)}</span>`}
function headerActions(){
 if(state.page==='dashboard')return `<div class="segmented" role="group" aria-label="总览统计时间">${[['yesterday','昨天'],['7d','近 7 天'],['30d','近 30 天']].map(([value,label])=>`<button class="btn" data-action="overview-period" data-period="${e(value)}" aria-pressed="${state.overviewPeriod===value}">${e(label)}</button>`).join('')}</div><button class="icon-button" data-action="refresh" title="刷新数据" aria-label="刷新数据">${icon('refresh')}</button>`;
 if(state.page==='articles')return `<a class="btn" href="/api/v1/export" download>${icon('download')}导出 CSV</a><button class="btn primary" data-action="new-article">${icon('plus')}记录发布</button>`;
 if(state.page==='reviews')return `<button class="btn primary" data-action="new-review">${icon('plus')}录入数据</button>`;
 if(state.settingsTab==='accounts')return `<button class="btn primary" data-action="new-account">${icon('plus')}添加账号</button>`;
 if(state.settingsTab==='keys')return `<button class="icon-button" data-action="key-help" aria-label="AI 凭据用途" aria-expanded="false" aria-controls="key-help">${icon('info')}</button><a href="/api-docs" class="btn" target="_blank" rel="noopener noreferrer">${icon('link',14)}接入文档</a><button class="btn primary" data-action="new-key">${icon('plus')}创建凭证</button>`;
 return `<button class="btn" data-action="refresh">${icon('refresh')}刷新</button>`;
}
function accountOptions(selected='',all=true,activeOnly=false){return `${all?'<option value="">全部账号</option>':''}${state.accounts.filter(a=>!activeOnly||a.active||a.id===selected).map(a=>`<option value="${e(a.id)}" ${a.id===selected?'selected':''}>${e(accountLabel(a))}${a.active?'':'（已停用）'}</option>`).join('')}`}
function pageHeader(){
 const count=state.page==='articles'?state.articleMeta?.total:state.page==='settings'&&state.settingsTab==='accounts'?rowsForAccount(state.accounts).length:null;
 const account=['articles','reviews'].includes(state.page)||(state.page==='settings'&&state.settingsTab==='accounts');
 return `<div class="heading-left"><h1>${e(nav.find(n=>n.id===state.page)?.label||'总览')}</h1><span id="page-count" class="page-count" ${count==null?'hidden':''}>${count==null?'':e(num(count))}</span></div><div class="head-actions">${account?`<label class="account-select"><span class="sr-only">切换运营账号</span><select id="global-account" aria-label="切换运营账号">${accountOptions(state.account)}</select></label>`:''}${headerActions()}<button class="icon-button" data-action="page-menu" aria-label="更多页面操作" aria-haspopup="menu" aria-expanded="false" aria-controls="page-menu">⋯</button></div>`;
}
